--通过item类型和itemid得到对应HOUSE表中的数据
function HouseUtil.GetHousePartsCfg(ResID)
    local Cfg = ItemCfg:FindCfgByKey(ResID)

    if Cfg ~= nil then
        local MappingTableName = Cfg.MappingTableName
        local KeyID = Cfg.KeyID

        --内装表
        if MappingTableName == ProtoRes.HOUSE_MAPPING_TABLE_ID.HOUSE_INDORR_TERRITORY then
            return HousingInteriorCfg:FindCfgByKey(KeyID)
        --外装表
        elseif MappingTableName == ProtoRes.HOUSE_MAPPING_TABLE_ID.HOUSE_TERRITORY then
            return HousingExteriorCfg:FindCfgByKey(KeyID)
        --家具表
        elseif MappingTableName == ProtoRes.HOUSE_MAPPING_TABLE_ID.HOUSE_FURNITURE then
            return HousingFurnitureCfg:FindCfgByKey(KeyID)
        --庭院表
        elseif MappingTableName == ProtoRes.HOUSE_MAPPING_TABLE_ID.HOUSE_YARD then
            return HousingYardCfg:FindCfgByKey(KeyID)
        end
    end

    return nil
end

function HouseUtil.GetHouseItemCfg(KeyID,MappingTableName)
    --内装表
    local Cfg = nil
    if MappingTableName == ProtoRes.HOUSE_MAPPING_TABLE_ID.HOUSE_INDORR_TERRITORY then
        Cfg = HousingInteriorCfg:FindCfgByKey(KeyID)
    --外装表
    elseif MappingTableName == ProtoRes.HOUSE_MAPPING_TABLE_ID.HOUSE_TERRITORY then
        Cfg = HousingExteriorCfg:FindCfgByKey(KeyID)
    --家具表
    elseif MappingTableName == ProtoRes.HOUSE_MAPPING_TABLE_ID.HOUSE_FURNITURE then
        Cfg =  HousingFurnitureCfg:FindCfgByKey(KeyID)
    --庭院表
    elseif MappingTableName == ProtoRes.HOUSE_MAPPING_TABLE_ID.HOUSE_YARD then
        Cfg =  HousingYardCfg:FindCfgByKey(KeyID)
    end

    if Cfg ~= nil then
        return ItemCfg:FindCfgByKey(Cfg.ItemID)
    end

    return Cfg
end

