function HouseUtil.ConvertServerFloorToClientFloor(ServerFloor)
    if ServerFloor == HouseCommon.ServerFloorCategory.FLOOR_CATEGORY_B1 then
        return HouseCommon.FloorCategory.FLOOR_CATEGORY_B1
    elseif ServerFloor == HouseCommon.ServerFloorCategory.FLOOR_CATEGORY_1F then
        return HouseCommon.FloorCategory.FLOOR_CATEGORY_1F
    elseif ServerFloor == HouseCommon.ServerFloorCategory.FLOOR_CATEGORY_2F then
        return HouseCommon.FloorCategory.FLOOR_CATEGORY_2F
    elseif ServerFloor == HouseCommon.ServerFloorCategory.FLOOR_CATEGORY_NONE then
        return HouseCommon.FloorCategory.FLOOR_CATEGORY_COMMON -- 这里混用None和Common可能有风险，后续看情况让后台修改大灯的floor数值
    end

    return HouseCommon.FloorCategory.FLOOR_CATEGORY_NONE
end

function HouseUtil.ConvertClientFloorToServerFloor(ClientFloor)
    if ClientFloor == HouseCommon.FloorCategory.FLOOR_CATEGORY_B1 then
        return HouseCommon.ServerFloorCategory.FLOOR_CATEGORY_B1
    elseif ClientFloor == HouseCommon.ServerFloorCategory.FLOOR_CATEGORY_1F then
        return HouseCommon.FloorCategory.FLOOR_CATEGORY_1F
    elseif ClientFloor == HouseCommon.ServerFloorCategory.FLOOR_CATEGORY_2F then
        return HouseCommon.FloorCategory.FLOOR_CATEGORY_2F
    elseif ClientFloor == HouseCommon.FloorCategory.FLOOR_CATEGORY_COMMON then
        return HouseCommon.ServerFloorCategory.FLOOR_CATEGORY_NONE
    end

    return HouseCommon.ServerFloorCategory.FLOOR_CATEGORY_NONE
end

