function HouseUtil.GetEstateID()
    local Cfgs = EstateInfoCfg:FindAllCfg()
    local MapResID = _G.PWorldMgr:GetCurrMapResID()

    for k,v in pairs(Cfgs) do
        if v.MapID == MapResID then
            return v.ID
        end
    end

    return 0
end

function HouseUtil.GetCurrentAreaSubID()
    local MajorPos = _G.PWorldMgr:GetMajorBirthPos()
    local MapID = _G.PWorldMgr:GetCurrMapResID()
    local Cfgs = EstateInfoCfg:FindAllCfg()

    for k,v in pairs(Cfgs) do
        if v.MapID == MapID then
            local InitAreaLeft = {x = v.InitAreaCenterX - (v.InitAreaExtentX / 2.0),y = v.InitAreaCenterY - (v.InitAreaExtentY / 2.0)}
            local InitAreaRight = {x = v.InitAreaCenterX + (v.InitAreaExtentX / 2.0),y = v.InitAreaCenterY + (v.InitAreaExtentY / 2.0)}

            if MajorPos.X >= InitAreaLeft.x and MajorPos.X <= InitAreaRight.x and MajorPos.Y >= InitAreaLeft.y and MajorPos.Y <= InitAreaRight.y then
                return 1
            else
                return 2
            end
        end
    end

    return 1
end

function HouseUtil.IsCurrentAreaBlock(Area,Block)
    return Area == math.ceil(Block / 30)
end

function HouseUtil.GetDecorateTabsIndexByMajorPosZ(HouseID)
    local TAB_INDEX_MAP = {
        [HouseCommon.HouseSize.HOUSE_SIZE_S] = {
            [HouseCommon.FloorCategory.FLOOR_CATEGORY_1F] = 1,
            [HouseCommon.FloorCategory.FLOOR_CATEGORY_B1] = 2
        },
        [HouseCommon.HouseSize.HOUSE_SIZE_M] = {
            [HouseCommon.FloorCategory.FLOOR_CATEGORY_2F] = 1,
            [HouseCommon.FloorCategory.FLOOR_CATEGORY_1F] = 2,
            [HouseCommon.FloorCategory.FLOOR_CATEGORY_B1] = 3
        },
        [HouseCommon.HouseSize.HOUSE_SIZE_L] = {
            [HouseCommon.FloorCategory.FLOOR_CATEGORY_2F] = 1,
            [HouseCommon.FloorCategory.FLOOR_CATEGORY_1F] = 2,
            [HouseCommon.FloorCategory.FLOOR_CATEGORY_B1] = 3,
            [HouseCommon.FloorCategory.FLOOR_CATEGORY_COMMON] = 4
        }
    }

    local HouseSize = _G.HousingMgr:GetHouseSize(HouseID)

    local MajorActor = MajorUtil.GetMajor()
    local MajorPos = MajorActor and MajorActor:FGetActorLocation() or _G.UE.FVector(0, 0, 0)
    local PosZ = MajorPos.Z

    local CurFloor = HouseCommon.FloorCategory.FLOOR_CATEGORY_1F
    if PosZ > 200 then
        CurFloor = HouseCommon.FloorCategory.FLOOR_CATEGORY_2F
    elseif PosZ > 0 then
        CurFloor = HouseCommon.FloorCategory.FLOOR_CATEGORY_1F
    else
        CurFloor = HouseCommon.FloorCategory.FLOOR_CATEGORY_B1
    end

    local SizeMap = TAB_INDEX_MAP[HouseSize] or TAB_INDEX_MAP[HouseCommon.HouseSize.HOUSE_SIZE_S]
    return SizeMap[CurFloor] or 1
end


return HouseUtil